import { createEffect, createSignal, mergeProps, Show, type ParentComponent } from "solid-js";

import { Activatable, ActivatableProps } from "#core/ui-next/components/activatable.jsx";
import { NavHelp } from "#core/ui-next/components/nav-help.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

interface MinusPlusButtonComponentProps extends ActivatableProps {
	type: string;
	dataDisabled: boolean;
}

const MinusPlusButtonComponent: ParentComponent<MinusPlusButtonComponentProps> = (props) => {
	const [mergedProps, setMergedProps] = createSignal<MinusPlusButtonComponentProps>({
		type: "minus",
		dataDisabled: false,
	});

	createEffect(() => {
		const audioObject = props.audio ?? {};
		audioObject.onPress ??= "data-audio-min-plus-button-press";
		audioObject.onFocus ??= "data-audio-min-plus-button-focus";

		const defaultProps: MinusPlusButtonComponentProps = { audio: audioObject, type: "minus", dataDisabled: false };
		const finalPropsObject = mergeProps(defaultProps, props);

		setMergedProps(finalPropsObject);
	});

	return (
		<Activatable
			{...mergedProps}
			disabled={mergedProps().dataDisabled}
			class={`relative p-1 cursor-pointer pointer-events-auto group flex items-center justify-center ${props.class ?? ""}`}
			classList={{
				"size-5": UI.getViewExperience() != UIViewExperience.Mobile,
				"size-6": UI.getViewExperience() == UIViewExperience.Mobile,
				"opacity-50": mergedProps().dataDisabled,
				...props.classList,
			}}
			name="MinusPlusButton"
		>
			<div
				class="absolute inset-0"
				classList={{
					"opacity-0": mergedProps().type == "minus",
				}}
			>
				<div class="absolute -inset-1\.5 img-questopen bg-no-repeat bg-center bg-contain" />
				<div class="absolute -inset-1\.5 bg-no-repeat bg-center bg-contain img-questopen-highlight transition-opacity opacity-0 group-hover\:opacity-100 group-focus\:opacity-100 group-pressed\:opacity-100" />
			</div>
			<div
				class="absolute inset-0"
				classList={{
					"opacity-0": mergedProps().type == "plus",
				}}
			>
				<div class="absolute -inset-1\.5 img-questclose bg-no-repeat bg-center bg-contain" />
				<div class="absolute -inset-1\.5 bg-no-repeat bg-center bg-contain img-questclose-highlight transition-opacity opacity-0 group-hover\:opacity-100 group-focus\:opacity-100 group-pressed\:opacity-100" />
			</div>
			<div
				class="absolute -inset-3"
				classList={{
					hidden: UI.getViewExperience() != UIViewExperience.Mobile,
				}}
			/>
			<Show when={!mergedProps().dataDisabled}>
				<NavHelp class="absolute" />
			</Show>
		</Activatable>
	);
};

/**
 * A Minus-Plus Button component.
 * A button with a state using the minus for deactivation and plus for activation.
 * ```tsx
 * // Example - Right Arrow
 * <MinusPlusButton onActivate={() => console.log("activated")} right={true} />
 * ```
 * Default implementation: {@link MinusPlusButtonComponent} Based on: {@link Activatable}
 * @param {MinusPlusButtonComponentProps} props See {@link MinusPlusButtonComponentProps} for a full list of properties
 *
 * Commonly Used Properties:
 * @param {boolean} props.type Set the button state (minus or plus) directly
 * @param {boolean} props.dataDisabled Disabled both visually and for input? Default: false
 * @param {string} props.hotkeyAction The name of a hotkey action which activates this component. Default: undefined
 * @param {string} props.name The name of the component set as the data-name property - useful for debugging or searching the DOM tree. Default: "Activatable"
 * @param {() => void} props.onActivate Event which triggers when the control is activated either through hotkey, mouse click, touch, or other user interaction. Default: undefined
 */
export const MinusPlusButton = ComponentRegistry.register({
	name: "MinusPlusButton",
	createInstance: MinusPlusButtonComponent,
	images: ["blp:hud_quest_open", "blp:hud_quest_open_hov", "blp:hud_quest_close", "blp:hud_quest_close_hov"],
});
